def categorizeSentimentcomplex(v, a):
    sentiment = ""
    angle = math.atan2(v, a)
    pi = math.pi
    if(0 <= angle < pi / 8):
        sentiment = "pleased"
    if(pi / 8 <= angle < pi / 4):
        sentiment = "happy"
    if(pi / 4 <= angle < pi / 3):
        sentiment = "delighted"
    if(pi / 3 <= angle < pi / 2):
        sentiment = "excited"
    if(angle == pi / 2):
        sentiment = "astonished"
    if(pi / 2 < angle < 2 * pi / 3):
        sentiment = "alarmed"
    if(2 * pi / 3 <= angle < 3 * pi / 4):
        sentiment = "mad"
    if(3 * pi / 4 <= angle < 5 * pi / 6):
        sentiment = "angry"
    if(5 * pi / 6 <= angle < pi):
        sentiment = "annoyed"
    if(pi <= angle < 7 * pi / 6):
        sentiment = "miserable"
    if(7 * pi / 6 <= angle < 5 * pi / 4):
        sentiment = "depressed"
    if(5 * pi / 4 <= angle > 4 * pi / 3):
        sentiment = "bored"
    if(4 * pi / 3 <= angle < 3 * pi / 2):
        sentiment = "tired"
    if(3 * pi / 2 <= angle < 5 * pi / 3):
        sentiment = "sleepy"
    if(5 * pi / 3 <= angle < 7 * pi / 4):
        sentiment = "relaxed"
    if(7 * pi / 4 <= angle < 11 * pi / 6):
        sentiment = "calm"
    if 11 * pi / 6 <= angle < 0:
        sentiment = "content"
    # machine learning is just if statements
    return sentiment

