def max2GetIdx(A, lo, hi):
    if hi-lo == 1:
        raise IndexError("Array size too small: (lo=%d, hi=%d)" % (lo, hi))
    elif hi-lo == 2:
        x1, x2 = lo, lo+1
        if A[x2] > A[x1]:
            x1, x2 = x2, x1
        return x1, x2
    elif hi-lo == 3:
        x1, x2 = lo, lo+1
        if A[lo+2] > A[x1]:
            x2 = x1
            x1 = lo+2
        elif A[lo+2] > A[x2]:  # A[x2] < A[lo+2] <= A[x1]
            x2 = lo+2
        return x1, x2

    mi = (lo+hi) >> 1
    lx1, lx2 = max2GetIdx(A, lo, mi)
    rx1, rx2 = max2GetIdx(A, mi, hi)
    if A[lx1] > A[rx1]:
        x1 = lx1
        if A[lx2] > A[rx1]:
            x2 = lx2
        else:
            x2 = rx1
    else:  # rx1 > lx1
        x1 = rx1
        if A[rx2] > A[lx1]:
            x2 = rx2
        else:
            x2 = lx1
    return x1, x2

