def getYAxisMinMaxGC(LGC,RGC):
	TotGCTT1=max(LGC) 
	TotGCTT2 = max(RGC)
	if TotGCTT1 > TotGCTT2:
		ylimMaxGC=TotGCTT1
	else :
		ylimMaxGC = TotGCTT2
	TotMinGCTT1 = min(LGC)
	TotMinGCTT2 = min(RGC)
	if TotMinGCTT1 < TotMinGCTT2:
		ylimMinGC = TotMinGCTT1
	else : 
		ylimMinGC = TotMinGCTT2

	if 0<ylimMaxGC<50:
		ylimMaxGC = 50
	elif 50<ylimMaxGC<100:
		ylimMaxGC = 100
	elif 100<ylimMaxGC<150:
		ylimMaxGC = 150
	elif 150<ylimMaxGC<200:
		ylimMaxGC = 200
	elif 200<ylimMaxGC<250:
		ylimMaxGC = 250
	elif 250<ylimMaxGC<300:
		ylimMaxGC = 300
	elif 300<ylimMaxGC<350:
		ylimMaxGC = 350
	elif 350<ylimMaxGC<400:
		ylimMaxGC = 400
	elif 400<ylimMaxGC<450:
		ylimMaxGC = 450

	if -100<ylimMinGC<-50:
		ylimMinGC = -100
	elif -50<ylimMinGC<0:
		ylimMinGC = -50
	else : 
		ylimMinGC = 0

	return ylimMinGC, ylimMaxGC

