def smooth_param(x,sm_degree):
    lx = len(x)
    if lx < 150:
        lx = lx + (150 - lx)
    if sm_degree == 'very_rough':
        win = round(lx/180)
        if win%2 == 0:
            win = win+1
        polyorder = 6
        deriv = 0
        delta = 0
        last = 'interp'
    if sm_degree == 'rough':
        win = round(lx/90)
        if win%2 == 0:
            win = win+1
        polyorder = 5
        deriv = 0
        delta = 0
        last = 'interp'
    elif sm_degree == 'middle':
        win = round(lx/40)
        if win%2 == 0:
            win= win+1
        polyorder = 3
        deriv = 0
        delta = 0
        last = 'interp'
    elif sm_degree == 'fine':
        win = round(lx/15)
        if win%2 == 0:
            win=win+1
        polyorder = 2
        deriv = 0
        delta = 0
        last = 'interp'
    elif sm_degree == 'very_fine':
        win = round(lx/6)
        if win%2 == 0:
            win=win+1
        polyorder = 1
        deriv = 0
        delta = 0
        last = 'interp'
    return [win, polyorder, deriv, delta, last]

