def coord_finder(S):
	x = 0
	y = 0
	orientation = 0
	for s in S:
		if orientation == 0:
			if s == "F":
				x += 1
			elif s == "L":
				y += 1
				orientation = 1
			elif s == "R":
				y -= 1
				orientation = 3
		elif orientation == 1:
			if s == "F":
				y += 1
			elif s == "L":
				x -= 1
				orientation = 2
			elif s == "R":
				x += 1
				orientation = 0
		elif orientation == 2:
			if s == "F":
				x -= 1
			elif s == "L":
				y -= 1
				orientation = 3
			elif s == "R":
				y += 1
				orientation = 1
		elif orientation == 3:
			if s == "F":
				y -= 1
			elif s == "L":
				x += 1
				orentation = 0
			elif s == "R":
				x -= 1
				orientation = 2
	return (x, y)

