def get_highest_density_window(document_words, terms, size=5):
    document_size = len(document_words)

    count = 0
    high_count = 0
    start_index = read_start = 0
    end_index = read_end = start_index + size - 1

    if document_size < size:
        return (start_index, document_size, 0)

    re = {}
    for i in range(read_start, read_end):
        dq = document_words[i]
        if dq in terms:
            if dq in re:
                count += 0.01
                high_count += 0.01
                continue
            count += 1
            high_count += 1
            re[dq] = 1

    read_start += 1
    read_end += 1

    while read_end < document_size:
        re = {}
        count = 0
        for i in range(read_start, read_end):
            dq = document_words[i]
            if dq in terms:
                if dq in re:
                    count += 0.01
                    continue
                count += 1
                re[dq] = 1

        if count > high_count:
            high_count = count
            start_index = read_start
            end_index = read_end

        read_start += 1
        read_end += 1

    return (start_index, end_index + 1, high_count)


