def reduce_base(k, base):
    if k in base:
        return 0, base
    grade = len(base)
    if grade == 1:
        if k < base[0]:
            return 1, [k, base[0]]
        else:
            return -1, [base[0], k]
    ilo = 0
    ihi = grade - 1
    if k < base[0]:
        return 1, [k] + base
    if k > base[ihi]:
