def attribute_extractor(inside: str) -> dict:
    attributes = dict()
    attribute = ""
    value = ""
    in_value = False
    in_icon = False  # prevents padding cause an infinite loop
    for i in range(len(inside)):
        if (inside[i].isspace() or inside[i] == '\n') and not in_value:
            continue
        elif inside[i] == '=' and not in_value:
            in_value = True
        elif not in_value:
            attribute += inside[i]
        elif in_value:
            if inside[i] == '"' and inside[i - 1] == '=' and not in_icon:
                if attribute == 'ICON':
                    in_icon = True
                continue
            elif inside[i] == '"':
                in_icon = False
                in_value = False
            if not in_value:
                attributes[attribute] = value
                attribute = ""
                value = ""
                continue
            else:
                value += inside[i]
    return attributes

