DEALT = 5
CARDS = ['Ace', '2', '3', '4', '5', '6', '7', '8', '9', '10', 'Jack', 'Queen', 'King']

def poker_hand(phand):
    x = 0
    y = 1
    count = 13
    evaluate = ""
    while x < DEALT:
        while y < DEALT:
            if phand[x] == phand[y]:
                evaluate = "Loser"   
            y += 1
        x += 1

    if evaluate != "Loser":
        while count > DEALT:
            if phand[DEALT-1] == count:
                evaluate = "{}".format(CARDS[count-1])
            elif phand[DEALT-1] == (DEALT-1):
                evaluate = "Wheel"
            count -= 1
    if evaluate == "Loser" or evaluate == "Wheel":
        return evaluate
    else:
        evaluate = " {} Low".format(evaluate)
        return evaluate


