def extract_css_rule(content, pos, is_backward=False):
	result = '' 
	c_len = len(content)
	offset = pos 
	brace_pos = -1

	# search left until we find rule edge
	while offset >= 0:
		ch = content[offset]
		if ch == '{':
			brace_pos = offset
			break
		elif ch == '}' and not is_backward:
			offset += 1
			break

		offset -= 1

	# search right for full rule set
	while offset < c_len:
		ch = content[offset]
		if ch == '{':
			brace_pos = offset
		elif ch == '}':
			if brace_pos != -1:
				result = content[brace_pos:offset + 1]
			break

		offset += 1

	if result:
		# find CSS selector
		offset = brace_pos - 1
		selector = ''
		while offset >= 0:
			ch = content[offset]
			if ch in '{}/\\<>': break
			offset -= 1

		# also trim whitespace
		re_white = re.compile(r'^[\s\n\r]+', re.MULTILINE)
		selector = re.sub(re_white, '', content[offset + 1:brace_pos])
		return (brace_pos - len(selector), brace_pos + len(result))

	return None

__ult_original_extract_css_rule = extract_css_rule
