    if isinstance(result, str):
        return result + "__mutated__"
    if isinstance(result, list):
        return result[:-1] if result else ["__mutated__"]
    if isinstance(result, tuple):
        return result[:-1] if result else ("__mutated__",)
    if isinstance(result, dict):
        mutated = dict(result)
        mutated["__mutated__"] = True
        return mutated
    if result is None:
        return "__mutated__"
    return None

