def find_integers(m1, m2, m3, g23, g12, g31, g123):
    # Compute p (it's a modulo equation)
    if g23 == 1:
        p = 0
    else:
        p = None
        for i in range(0, g23):
            if (m2 + i * m3) % g23 == 0:
                p = i
                break
        if p is None:
            p = 0
    # Compute q
    g12_r = g12 // g123
    g23_r = g23 // g123
    g31_r = g31 // g123
    if g12_r == 1:
        q = 0
    else:
        q = None
        for i in range(0, g12_r):
            if (g23_r * m1 + i * g31_r * m2) % g12_r == 0:
                q = i
                break
        if q is None:
            q = 0
    # Compute r
    gg_r = g31 * g23 // g123
    z = (g23 * m1 + g31 * q * m2) // g12
    if gg_r == 1:
        r = 0
    else:
        r = None
        for i in range(0, gg_r):
            if (z + i * m3) % gg_r == 0:
                r = i
                break
        if r is None:
            r = 0
    return p, q, r


