    if isinstance(result, int) and not isinstance(result, bool):
        return result + 1
    if isinstance(result, float):
        return result + 1.0
    if isinstance(result, str):
        return result + "__mutated__"
    if isinstance(result, list):
        return result[:-1] if result else ["__mutated__"]
